import React from 'react';
import { useAuth } from '@/contexts/AuthContext';

interface FinanceiroPermissionGuardProps {
  children: React.ReactNode;
  requiredPermission: string;
  fallback?: React.ReactNode;
}

/**
 * Maps legacy guard permission names to the actual UserPermissions flags
 * generated by permissions.ts.  A user passes if they hold ANY of the
 * mapped flags (OR semantics within each alias group).
 */
const PERMISSION_ALIASES: Record<string, string[]> = {
  // Generic financial access
  VIEW_FINANCIAL:   ['FINANCIAL_READ'],
  MANAGE_FINANCIAL: ['FINANCIAL_WRITE'],

  // Pagamentos — SUPRIMENTOS and ANALISTA_SUPRIMENTOS have FINANCIAL_READ + FINANCIAL_PAYABLE_READ
  VIEW_PAGAMENTOS:    ['FINANCIAL_READ', 'FINANCIAL_PAYABLE_READ'],
  MANAGE_PAGAMENTOS:  ['FINANCIAL_WRITE', 'FINANCIAL_PAYABLE_WRITE'],
  EXECUTE_PAGAMENTOS: ['FINANCIAL_WRITE', 'FINANCIAL_PAYABLE_WRITE'],

  // Contas a Pagar
  VIEW_CONTAS_PAGAR:    ['FINANCIAL_READ', 'FINANCIAL_PAYABLE_READ'],
  MANAGE_CONTAS_PAGAR:  ['FINANCIAL_WRITE', 'FINANCIAL_PAYABLE_WRITE'],
  APPROVE_CONTAS_PAGAR: ['FINANCIAL_WRITE', 'FINANCIAL_PAYABLE_WRITE'],

  // Contas a Receber
  VIEW_CONTAS_RECEBER:    ['FINANCIAL_READ', 'FINANCIAL_RECEIVABLE_READ'],
  MANAGE_CONTAS_RECEBER:  ['FINANCIAL_WRITE', 'FINANCIAL_RECEIVABLE_WRITE'],
  APPROVE_CONTAS_RECEBER: ['FINANCIAL_WRITE', 'FINANCIAL_RECEIVABLE_WRITE'],

  // Fluxo de Caixa
  VIEW_FLUXO_CAIXA:   ['FINANCIAL_READ', 'FINANCIAL_CASHFLOW_READ'],
  MANAGE_FLUXO_CAIXA: ['FINANCIAL_WRITE', 'FINANCIAL_CASHFLOW_READ'],

  // Relatórios Financeiros
  VIEW_RELATORIOS_FINANCEIROS:     ['FINANCIAL_READ', 'REPORTS_READ'],
  GENERATE_RELATORIOS_FINANCEIROS: ['FINANCIAL_READ', 'REPORTS_GENERATE'],
  EXPORT_RELATORIOS_FINANCEIROS:   ['FINANCIAL_READ', 'REPORTS_EXPORT'],
};

export const FinanceiroPermissionGuard: React.FC<FinanceiroPermissionGuardProps> = ({
  children,
  requiredPermission,
  fallback
}) => {
  const { user } = useAuth();

  /** Checks a single real permission key against the user's permission map. */
  const hasRealPermission = (perm: string): boolean => {
    const perms: any = user?.permissions;
    if (!perms) return false;
    if (Array.isArray(perms)) {
      return perms.some((p: string) => p === perm || p === 'ALL_PERMISSIONS');
    }
    // Object of boolean flags
    return Boolean(perms.ALL_PERMISSIONS || perms[perm]);
  };

  /**
   * Resolves a permission name (possibly a legacy alias) and returns true
   * if the user holds ANY of the corresponding real permissions.
   */
  const resolvePermission = (perm: string): boolean => {
    if (hasRealPermission('ALL_PERMISSIONS')) return true;
    if (hasRealPermission(perm)) return true;
    const aliases = PERMISSION_ALIASES[perm];
    if (aliases && aliases.length > 0) {
      return aliases.some(alias => hasRealPermission(alias));
    }
    return false;
  };

  // Gate 1 — does the user have any financial access at all?
  const hasFinancialAccess =
    resolvePermission('VIEW_FINANCIAL') ||
    resolvePermission('MANAGE_FINANCIAL') ||
    resolvePermission(requiredPermission);

  if (!hasFinancialAccess) {
    return fallback != null ? <>{fallback}</> : (
      <div className="p-6 text-center">
        <div className="text-red-500 text-6xl mb-4">🔒</div>
        <h3 className="text-lg font-semibold text-gray-800 mb-2">
          Acesso Restrito
        </h3>
        <p className="text-gray-600">
          Você não tem permissão para acessar esta funcionalidade financeira.
        </p>
        <p className="text-sm text-gray-500 mt-2">
          Entre em contato com o administrador para solicitar acesso.
        </p>
      </div>
    );
  }

  // Gate 2 — does the user have the specific action permission?
  const hasSpecificPermission =
    resolvePermission(requiredPermission) ||
    resolvePermission('MANAGE_FINANCIAL');

  if (!hasSpecificPermission) {
    return fallback != null ? <>{fallback}</> : (
      <div className="p-6 text-center">
        <div className="text-yellow-500 text-6xl mb-4">⚠️</div>
        <h3 className="text-lg font-semibold text-gray-800 mb-2">
          Permissão Insuficiente
        </h3>
        <p className="text-gray-600">
          Você não tem permissão para executar esta ação.
        </p>
        <p className="text-sm text-gray-500 mt-2">
          Permissão necessária: {requiredPermission}
        </p>
      </div>
    );
  }

  return <>{children}</>;
};

// Componentes específicos para cada área financeira
export const ContasAPagarGuard: React.FC<{ children: React.ReactNode; action?: 'view' | 'manage' | 'approve' }> = ({
  children,
  action = 'view'
}) => {
  const permission =
    action === 'view'   ? 'VIEW_CONTAS_PAGAR' :
    action === 'manage' ? 'MANAGE_CONTAS_PAGAR' :
                          'APPROVE_CONTAS_PAGAR';
  return (
    <FinanceiroPermissionGuard requiredPermission={permission}>
      {children}
    </FinanceiroPermissionGuard>
  );
};

